-- Deep Cut Theatre — one verified film for each of the ten new channels
-- (migration 0008 added the channels; this fills them). Two research passes
-- checked every candidate against the same bar the first twelve were held to:
-- hosted on the filmmaker's own official Vimeo/YouTube account (confirmed via
-- the platform's own oEmbed response, not a search snippet), and a pedigree
-- line that states the exact award and year rather than blurring "shortlisted"
-- into "won". Several strong, real films were found and dropped anyway —
-- rented via Vimeo On Demand, distributed through a paywalled streamer, or
-- hosted only by a licensed reseller rather than the filmmaker themselves —
-- because none of that clears the bar this room runs on.
--
-- One embed was caught and rejected specifically: a Sundance-winning short
-- whose Vimeo oEmbed came back with domain_status_code 403, meaning the
-- uploader restricted which sites may embed it and thedeepcut.xyz isn't on
-- that list. It would render a black box instead of a film, so it isn't here.

insert into public.shorts
  (id, title, director, year, runtime_sec, source, video_id, channels, pedigree, synopsis, thumb)
values
  ('alternative-math', 'Alternative Math', 'David Maddox', 2017, 540, 'youtube', 'Zh3Yz3PiXZw', ARRAY['funny']::text[], 'Frostbite International Film Festival 2018 — Best Comedy Short (won)', 'A beloved elementary teacher''s career implodes into a national media circus after she marks a student''s "2+2=22" answer wrong.', 'https://i.ytimg.com/vi/Zh3Yz3PiXZw/hqdefault.jpg'),
  ('ship-a-visual-poem', '-Ship: A Visual Poem', 'Terrance Daye', 2020, 783, 'vimeo', '436144408', ARRAY['grown']::text[], 'Sundance 2020 — Short Film Jury Award, U.S. Fiction (won)', 'On the day of his older cousin''s funeral, a young Black boy wanders the grieving house trying on his cousin''s clothes and jewelry, quietly working out what kind of man he''s supposed to become.', 'https://i.vimeocdn.com/video/921189825-2681539b4e099c875886e1079f17005075667563aa407a9e80bc159f79f55466-d_295x166?region=us'),
  ('in-a-heartbeat', 'In a Heartbeat', 'Beth David & Esteban Bravo', 2017, 240, 'youtube', '2REkk9SCRn0', ARRAY['loud']::text[], 'Student Academy Award, Animation — Gold Medal (won) · GLAAD Media Award, Special Recognition (won), 2017', 'A closeted boy''s heart literally leaps out of his chest to chase the boy he has a crush on, risking outing him in front of the whole schoolyard.', 'https://i.ytimg.com/vi/2REkk9SCRn0/hqdefault.jpg'),
  ('dandelion', 'Dandelion', 'Fiona Obertinca', 2025, 1200, 'youtube', 'Z2rObPKVqm8', ARRAY['loud']::text[], 'Palm Springs International ShortFest 2025 — Best Student Short (won)', 'In 1970s Los Angeles, a rebellious queer teenager freshly kicked out of another foster home spends one long night crossing the city with the social worker tasked with placing her before sunrise.', 'https://i.ytimg.com/vi/Z2rObPKVqm8/hqdefault.jpg'),
  ('curfew', 'Curfew', 'Shawn Christensen', 2012, 1185, 'vimeo', '41187986', ARRAY['wrong']::text[], 'Academy Award, Best Live Action Short Film (won), 2013', 'A suicidal man''s night takes a sharp turn when his estranged sister asks him to babysit his young niece for a few hours.', 'https://i.vimeocdn.com/video/287489910-202e105dc4dc153dffc67ca8865c1f5e0bf095c38bc9ca56b18d523f859858c0-d_295x166?region=us'),
  ('robots-of-brixton', 'Robots of Brixton', 'Kibwe Tavares', 2011, 336, 'vimeo', '25092596', ARRAY['future']::text[], 'Sundance 2012 — Special Jury Award, Animation Direction (won)', 'In a near-future Brixton run down by poverty and unemployment, a police raid on a robot underclass''s last safe space reignites the violence of the 1981 riots.', 'https://i.vimeocdn.com/video/165023782-a73f27e2b4c45a316039a14a6b4c28429aae64395f9855b4fd3f4f9a115c5fa8-d_295x166?region=us'),
  ('shok', 'Shok', 'Jamie Donoughue', 2015, 1256, 'vimeo', '564100836', ARRAY['front']::text[], 'Academy Award nomination, Best Live Action Short Film, 2016 · Aspen Shortsfest 2015 — Best Drama, Audience Special Recognition, Youth Jury Award (won)', 'Two boyhood best friends in 1990s Kosovo run cigarette-paper errands for occupying Serbian soldiers, until a demand for one boy''s bicycle fractures their friendship in a way neither survives intact.', 'https://i.vimeocdn.com/video/1166447650-3565f2c0ed62792440636bb906fd26e100a2c18f39354976838fca13850fa8fe-d_295x166?region=us'),
  ('buzkashi-boys', 'Buzkashi Boys', 'Sam French', 2012, 1788, 'vimeo', '449024041', ARRAY['front']::text[], 'Academy Award nomination, Best Live Action Short Film, 2013 · Raindance Film Festival — Best International Short (won)', 'Two Kabul teenagers — a street kid and a blacksmith''s son — chase very different versions of manhood through Afghanistan''s brutal national sport of buzkashi.', 'https://i.vimeocdn.com/video/942400306-4e950f55c84a06aecac9f162809bdd56875ca0ab871d9b82d798eac59e853a4c-d_295x166?region=us'),
  ('a-concerto-is-a-conversation', 'A Concerto Is a Conversation', 'Ben Proudfoot & Kris Bowers', 2021, 780, 'youtube', 'LoEZR5miMvo', ARRAY['sound']::text[], 'Academy Award nomination, Best Documentary Short Subject, 2021 · Hot Docs 2021 — Audience Award, Short Films (won)', 'Film composer Kris Bowers interviews his 91-year-old grandfather about the family''s journey from Jim Crow-era Florida to the Walt Disney Concert Hall.', 'https://i.ytimg.com/vi/LoEZR5miMvo/hqdefault.jpg'),
  ('haulout', 'Haulout', 'Evgenia Arbugaeva & Maxim Arbugaev', 2022, 1500, 'youtube', '8mKBZ9dy5fQ', ARRAY['wild']::text[], 'Academy Award nomination, Best Documentary Short Film, 2023', 'A marine biologist alone on a remote Siberian shore documents roughly 100,000 walruses forced onto land as the vanishing sea ice that once held them collapses.', 'https://i.ytimg.com/vi/8mKBZ9dy5fQ/hqdefault.jpg'),
  ('the-queen-of-basketball', 'The Queen of Basketball', 'Ben Proudfoot', 2021, 1320, 'youtube', 'vPFkcoTfr7g', ARRAY['over']::text[], 'Academy Award, Best Documentary Short Subject (won), 2022', 'Lusia Harris, the only woman ever officially drafted by an NBA team, tells her own story of dominating women''s basketball in the 1970s before the sport had a real stage for her.', 'https://i.ytimg.com/vi/vPFkcoTfr7g/hqdefault.jpg'),
  ('former-cult-member-hears-music', 'Former Cult Member Hears Music For The First Time', 'Kristoffer Borgli', 2020, 717, 'vimeo', '392348731', ARRAY['rails']::text[], 'Sundance 2020 — Official Selection · Vimeo Staff Pick Premiere', 'A woman raised in an isolated, abusive family is brought into a staged "experiment" to hear recorded music for the first time in her life, with reactions that spiral into something stranger than expected.', 'https://i.vimeocdn.com/video/857422409-7a02213179fc7713d07aab0f24cd3b7a7d21cc117bcb9884643f1c0d5fb80f93-d_295x166?region=us')
on conflict (id) do nothing;
